<?php
require __DIR__.'/../app/bootstrap.php';
$page=$_GET['page']??'home';$method=$_SERVER['REQUEST_METHOD'];
function property_row($id){$q=db()->prepare("SELECT p.*,u.name owner_name FROM properties p JOIN users u ON u.id=p.owner_id WHERE p.id=?");$q->execute([$id]);return $q->fetch();}
function owned_property($id){$p=property_row($id);if(!$p) {http_response_code(404);exit('Property not found');}$u=current_user();if(!($u['role']==='admin'||(int)$p['owner_id']===(int)$u['id']||(int)$p['agent_id']===(int)$u['id'])){http_response_code(403);exit('Not authorised');}return $p;}
if($method==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
 switch($action){
 case 'register':
  $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'tenant';$pass=$_POST['password']??'';
  if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['tenant','landlord'],true)||strlen($pass)<10||$pass!==($_POST['password_confirm']??''))throw new Exception('Check your name, email, role and password (minimum 10 characters; confirmation must match).');
  $q=db()->prepare('INSERT INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?,?)');$q->execute([$name,$email,trim($_POST['phone']??''),password_hash($pass,PASSWORD_DEFAULT),$role]);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>$role];session_regenerate_id(true);flash('success','Account created.');redirect_to('index.php?page=dashboard');
 case 'login':
  $q=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$q->execute([strtolower(trim($_POST['email']??''))]);$u=$q->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password_hash'])||$u['status']!=='active')throw new Exception('Invalid credentials or inactive account.');$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];session_regenerate_id(true);flash('success','Welcome back.');redirect_to('index.php?page=dashboard');
 case 'logout':require_login();unset($_SESSION['user']);session_regenerate_id(true);flash('success','You have signed out.');redirect_to('index.php');
 case 'property_create':require_role('landlord');
  $title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=$_POST['property_type']??'';$city=trim($_POST['city']??'');$area=trim($_POST['area']??'');$rent=(float)($_POST['rent_amount']??0);$period=$_POST['rent_period']??'month';$currency=$_POST['currency']??'SLE';
  if(strlen($title)<5||strlen($desc)<20||!in_array($type,['apartment','house','room','commercial'])||!$city||!$area||$rent<=0||!in_array($period,['week','month','year'])||!in_array($currency,['SLE','USD']))throw new Exception('Complete all required property details correctly. Description must be at least 20 characters.');
  $q=db()->prepare("INSERT INTO properties(owner_id,title,description,property_type,city,district,area,public_location,bedrooms,bathrooms,rent_amount,currency,rent_period,deposit_amount,available_from,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending_review')");$q->execute([current_user()['id'],$title,$desc,$type,$city,trim($_POST['district']??''),$area,trim($_POST['public_location']??''),($_POST['bedrooms']??'')===''?null:(int)$_POST['bedrooms'],($_POST['bathrooms']??'')===''?null:(int)$_POST['bathrooms'],$rent,$currency,$period,($_POST['deposit_amount']??'')===''?null:(float)$_POST['deposit_amount'],($_POST['available_from']??'')?:null]);$pid=(int)db()->lastInsertId();
  if(!empty($_FILES['images']['name'][0])){foreach($_FILES['images']['tmp_name'] as $i=>$tmp){if($_FILES['images']['error'][$i]!==UPLOAD_ERR_OK)continue;if($_FILES['images']['size'][$i]>cfg('max_upload_bytes'))continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)continue;$new=bin2hex(random_bytes(12)).'.'.$ext;if(move_uploaded_file($tmp,cfg('upload_dir').'/'.$new)){$q=db()->prepare('INSERT INTO property_images(property_id,file_name,alt_text,sort_order) VALUES(?,?,?,?)');$q->execute([$pid,$new,$title,$i]);}}}
  audit('property_submitted','property',$pid);flash('success','Property submitted for administrator review.');redirect_to('index.php?page=dashboard');
 case 'assign_agent':require_role('landlord');$pid=(int)$_POST['property_id'];$q=db()->prepare('SELECT owner_id FROM properties WHERE id=?');$q->execute([$pid]);$pr=$q->fetch();if(!$pr||(int)$pr['owner_id']!==(int)current_user()['id'])throw new Exception('You can assign agents only to your own properties.');$email=strtolower(trim($_POST['agent_email']??''));$agentId=null;if($email!==''){$q=db()->prepare("SELECT id FROM users WHERE email=? AND role='agent' AND status='active'");$q->execute([$email]);$agentId=$q->fetchColumn();if(!$agentId)throw new Exception('No active agent account matches that email.');}$q=db()->prepare('UPDATE properties SET agent_id=? WHERE id=?');$q->execute([$agentId,$pid]);audit('property_agent_assignment_updated','property',$pid,['agent_id'=>$agentId]);flash('success','Agent assignment updated.');redirect_to('index.php?page=dashboard');
 case 'listing_decision':require_role('admin');$id=(int)$_POST['property_id'];$status=$_POST['status']??'';if(!in_array($status,['published','needs_changes','rejected','suspended'],true))throw new Exception('Invalid review decision.');$note=trim($_POST['review_note']??'');$q=db()->prepare("UPDATE properties SET status=?,review_note=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status IN ('pending_review','needs_changes')");$q->execute([$status,$note,current_user()['id'],$id]);audit('listing_'.$status,'property',$id,['note'=>$note]);flash('success','Listing review saved.');redirect_to('index.php?page=admin');
 case 'favourite':require_role('tenant');$pid=(int)$_POST['property_id'];$q=db()->prepare('SELECT id FROM saved_properties WHERE tenant_id=? AND property_id=?');$q->execute([current_user()['id'],$pid]);if($q->fetch()){$q=db()->prepare('DELETE FROM saved_properties WHERE tenant_id=? AND property_id=?');$q->execute([current_user()['id'],$pid]);}else{$q=db()->prepare('INSERT IGNORE INTO saved_properties(tenant_id,property_id) VALUES(?,?)');$q->execute([current_user()['id'],$pid]);}flash('success','Saved-property list updated.');redirect_to('index.php?page=property&id='.$pid);
 case 'viewing':require_role('tenant');$pid=(int)$_POST['property_id'];$dt=$_POST['requested_at']??'';if(strtotime($dt)<=time())throw new Exception('Choose a future viewing date and time.');$p=property_row($pid);if(!$p||$p['status']!=='published')throw new Exception('This listing is not available.');$q=db()->prepare('INSERT INTO viewing_requests(property_id,tenant_id,requested_at,message) VALUES(?,?,?,?)');$q->execute([$pid,current_user()['id'],date('Y-m-d H:i:s',strtotime($dt)),trim($_POST['message']??'')]);audit('viewing_requested','property',$pid);flash('success','Viewing request submitted.');redirect_to('index.php?page=property&id='.$pid);
 case 'application':require_role('tenant');$pid=(int)$_POST['property_id'];$p=property_row($pid);if(!$p||$p['status']!=='published')throw new Exception('This listing is not available.');$msg=trim($_POST['message']??'');if(strlen($msg)<10)throw new Exception('Please provide a short introduction (at least 10 characters).');$q=db()->prepare('INSERT INTO rental_applications(property_id,tenant_id,message) VALUES(?,?,?)');$q->execute([$pid,current_user()['id'],$msg]);audit('rental_application_submitted','property',$pid);flash('success','Rental application submitted.');redirect_to('index.php?page=dashboard');
 case 'decision':require_login();$id=(int)$_POST['record_id'];$kind=$_POST['kind']??'';$status=$_POST['status']??'';$note=trim($_POST['note']??'');if($kind==='application'){$q=db()->prepare('SELECT r.*,p.owner_id,p.agent_id FROM rental_applications r JOIN properties p ON p.id=r.property_id WHERE r.id=?');$q->execute([$id]);$r=$q->fetch();$allowed=$r&&(current_user()['role']==='admin'||(int)$r['owner_id']===(int)current_user()['id']||(int)$r['agent_id']===(int)current_user()['id']);if(!$allowed||!in_array($status,['under_review','approved','declined']))throw new Exception('Not authorised or invalid decision.');$q=db()->prepare('UPDATE rental_applications SET status=?,decision_note=? WHERE id=?');$q->execute([$status,$note,$id]);}elseif($kind==='viewing'){$q=db()->prepare('SELECT v.*,p.owner_id,p.agent_id FROM viewing_requests v JOIN properties p ON p.id=v.property_id WHERE v.id=?');$q->execute([$id]);$r=$q->fetch();$allowed=$r&&(current_user()['role']==='admin'||(int)$r['owner_id']===(int)current_user()['id']||(int)$r['agent_id']===(int)current_user()['id']);if(!$allowed||!in_array($status,['accepted','declined','completed','cancelled']))throw new Exception('Not authorised or invalid decision.');$q=db()->prepare('UPDATE viewing_requests SET status=?,decision_note=? WHERE id=?');$q->execute([$status,$note,$id]);}else throw new Exception('Unknown record type.');audit($kind.'_decision','record',$id,['status'=>$status]);flash('success','Decision updated.');redirect_to('index.php?page=dashboard');
 case 'maintenance':require_role('tenant');$pid=(int)$_POST['property_id'];$p=property_row($pid);if(!$p||!in_array($p['status'],['published','rented']))throw new Exception('Property not found.');$category=$_POST['category']??'other';if(!in_array($category,['plumbing','electrical','structural','appliance','other']))throw new Exception('Invalid category.');$desc=trim($_POST['description']??'');if(strlen($desc)<10)throw new Exception('Please describe the issue in at least 10 characters.');$q=db()->prepare('INSERT INTO maintenance_requests(property_id,tenant_id,category,description,urgency) VALUES(?,?,?,?,?)');$q->execute([$pid,current_user()['id'],$category,$desc,($_POST['urgency']??'normal')==='high'?'high':'normal']);audit('maintenance_submitted','property',$pid);flash('success','Maintenance request submitted.');redirect_to('index.php?page=dashboard');
 case 'maintenance_update':require_login();$id=(int)$_POST['record_id'];$status=$_POST['status']??'';$q=db()->prepare('SELECT m.*,p.owner_id,p.agent_id FROM maintenance_requests m JOIN properties p ON p.id=m.property_id WHERE m.id=?');$q->execute([$id]);$r=$q->fetch();$allowed=$r&&(current_user()['role']==='admin'||(int)$r['owner_id']===(int)current_user()['id']||(int)$r['agent_id']===(int)current_user()['id']);if(!$allowed||!in_array($status,['open','in_progress','waiting','resolved','closed']))throw new Exception('Not authorised or invalid status.');$q=db()->prepare('UPDATE maintenance_requests SET status=?,resolution_note=? WHERE id=?');$q->execute([$status,trim($_POST['note']??''),$id]);audit('maintenance_status_updated','maintenance_request',$id);flash('success','Maintenance status updated.');redirect_to('index.php?page=dashboard');
 default:throw new Exception('Unknown action.');
 }
 }catch(Throwable $ex){flash('error',$ex instanceof PDOException?'The request could not be saved. Check that the information is valid and try again.':$ex->getMessage());$back=$_SERVER['HTTP_REFERER']??url('index.php');header('Location: '.$back);exit;}
}
if($page==='logout'){if(current_user()){unset($_SESSION['user']);session_regenerate_id(true);}redirect_to('index.php');}
$u=current_user();$flashes=consume_flashes();
function header_html($title){global $u,$flashes;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($title)?> · RentEasy SL</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="top"><a class="brand" href="index.php"><img src="assets/brand/renteasy_sl_logo.png" alt="RentEasy SL"></a><nav><a href="index.php">Find property</a><?php if(current_user()):?><a href="index.php?page=dashboard">Dashboard</a><?php if(current_user()['role']==='landlord'):?><a href="index.php?page=create">Add property</a><?php endif;?><?php if(current_user()['role']==='admin'):?><a href="index.php?page=admin">Admin review</a><?php endif;?><span><?=e(current_user()['name'])?> · <?=e(current_user()['role'])?></span><form method="post" class="inline"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="link">Sign out</button></form><?php else:?><a href="index.php?page=login">Sign in</a><a class="btn small" href="index.php?page=register">Create account</a><?php endif;?></nav></header><main class="container"><?php foreach($flashes as $k=>$v):?><div class="alert <?=e($k)?>"><?=e($v)?></div><?php endforeach;?><?php }
function footer_html(){?></main><footer><div>© <?=date('Y')?> RentEasy SL · Find · Rent · Manage</div><small>Demonstration platform. Listing review is not legal title verification. RentEasy does not collect rental payments.</small></footer></body></html><?php }
function money($v,$c){return e($c).' '.number_format((float)$v,2);}
if($page==='login'||$page==='register'){header_html($page==='login'?'Sign in':'Create account');?><section class="auth"><h1><?=$page==='login'?'Welcome back':'Create your RentEasy account'?></h1><form method="post" class="panel"><?=csrf_field()?><input type="hidden" name="action" value="<?=$page?>"><?php if($page==='register'):?><label>Full name<input name="name" required maxlength="120"></label><label>Phone (optional)<input name="phone"></label><label>Account type<select name="role"><option value="tenant">Tenant</option><option value="landlord">Landlord</option></select></label><?php endif;?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required minlength="10"></label><?php if($page==='register'):?><label>Confirm password<input type="password" name="password_confirm" required minlength="10"></label><?php endif;?><button class="btn full"><?=$page==='login'?'Sign in':'Create account'?></button></form></section><?php footer_html();exit;}
if($page==='create'){require_role('landlord');header_html('Add property');?><h1>Submit a property</h1><form method="post" enctype="multipart/form-data" class="panel formgrid"><?=csrf_field()?><input type="hidden" name="action" value="property_create"><label class="wide">Property title<input name="title" required maxlength="150"></label><label>Property type<select name="property_type"><option>apartment</option><option>house</option><option>room</option><option>commercial</option></select></label><label>City<input name="city" value="Freetown" required></label><label>District<input name="district"></label><label>Area / neighbourhood<input name="area" required></label><label class="wide">Public location description (do not enter private access details)<input name="public_location"></label><label>Bedrooms<input type="number" min="0" max="30" name="bedrooms"></label><label>Bathrooms<input type="number" min="0" max="30" name="bathrooms"></label><label>Rent amount<input type="number" step="0.01" min="0.01" name="rent_amount" required></label><label>Currency<select name="currency"><option>SLE</option><option>USD</option></select></label><label>Rent period<select name="rent_period"><option>month</option><option>week</option><option>year</option></select></label><label>Deposit amount<input type="number" step="0.01" min="0" name="deposit_amount"></label><label>Available from<input type="date" name="available_from"></label><label class="wide">Description<textarea name="description" rows="5" required minlength="20"></textarea></label><label class="wide">Property photos (JPG, PNG, WEBP; max 4MB each)<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple></label><button class="btn">Submit for review</button></form><?php footer_html();exit;}
if($page==='property'){$id=(int)($_GET['id']??0);$p=property_row($id);if(!$p||($p['status']!=='published'&&!($u&&($u['role']==='admin'||(int)$p['owner_id']===(int)$u['id'])))){http_response_code(404);exit('Property not found');}$q=db()->prepare('SELECT * FROM property_images WHERE property_id=? ORDER BY sort_order,id');$q->execute([$id]);$imgs=$q->fetchAll();header_html($p['title']);?><a href="index.php">← Back to search</a><section class="detail"><div><?php if($imgs):?><img class="heroimg" src="uploads/properties/<?=e($imgs[0]['file_name'])?>" alt="Property photo"><?php else:?><div class="placeholder large">RentEasy SL</div><?php endif;?><h1><?=e($p['title'])?></h1><p><?=e($p['city'])?> · <?=e($p['district'])?> · <?=e($p['area'])?></p><h2 class="price"><?=money($p['rent_amount'],$p['currency'])?> / <?=e($p['rent_period'])?></h2><p><?=nl2br(e($p['description']))?></p><p><?=e($p['bedrooms']??'—')?> bedrooms · <?=e($p['bathrooms']??'—')?> bathrooms · <?=e($p['property_type'])?></p><p class="muted">Listed by <?=e($p['owner_name'])?>. Contact details and exact private addresses are not published.</p></div><aside><?php if($u&&$u['role']==='tenant'):?><form method="post" class="panel"><?=csrf_field()?><input type="hidden" name="action" value="favourite"><input type="hidden" name="property_id" value="<?=$id?>"><button class="btn secondary full">Save / remove favourite</button></form><form method="post" class="panel"><?=csrf_field()?><input type="hidden" name="action" value="viewing"><input type="hidden" name="property_id" value="<?=$id?>"><h3>Request a viewing</h3><label>Date and time<input type="datetime-local" name="requested_at" required></label><label>Message<textarea name="message"></textarea></label><button class="btn full">Request viewing</button></form><form method="post" class="panel"><?=csrf_field()?><input type="hidden" name="action" value="application"><input type="hidden" name="property_id" value="<?=$id?>"><h3>Apply to rent</h3><label>Introduce yourself<textarea name="message" required minlength="10"></textarea></label><button class="btn full">Submit application</button></form><form method="post" class="panel"><?=csrf_field()?><input type="hidden" name="action" value="maintenance"><input type="hidden" name="property_id" value="<?=$id?>"><h3>Maintenance request</h3><label>Category<select name="category"><option>plumbing</option><option>electrical</option><option>structural</option><option>appliance</option><option>other</option></select></label><label>Urgency<select name="urgency"><option>normal</option><option>high</option></select></label><label>Description<textarea name="description" minlength="10"></textarea></label><button class="btn secondary full">Submit issue</button><small>For actual tenants only; the demo records a request but does not verify tenancy.</small></form><?php elseif(!$u):?><div class="panel"><h3>Interested in this property?</h3><a class="btn full" href="index.php?page=login">Sign in to request a viewing</a></div><?php endif;?></aside></section><?php footer_html();exit;}
if($page==='admin'){require_role('admin');$rows=db()->query("SELECT p.*,u.name owner_name FROM properties p JOIN users u ON u.id=p.owner_id WHERE p.status IN ('pending_review','needs_changes') ORDER BY p.created_at")->fetchAll();header_html('Administrator listing review');?><h1>Listing review queue</h1><p class="muted">Review is an internal platform checklist. It does not certify ownership, title, structural safety or legal status.</p><?php foreach($rows as $r):?><article class="panel record"><h3><?=e($r['title'])?></h3><p><?=e($r['city'])?> · <?=e($r['area'])?> · <?=money($r['rent_amount'],$r['currency'])?> / <?=e($r['rent_period'])?></p><p>Submitted by <?=e($r['owner_name'])?></p><p><?=e($r['description'])?></p><form method="post" class="inlineform"><?=csrf_field()?><input type="hidden" name="action" value="listing_decision"><input type="hidden" name="property_id" value="<?=$r['id']?>"><input name="review_note" placeholder="Review note"><button class="btn small" name="status" value="published">Publish</button><button class="btn small secondary" name="status" value="needs_changes">Request changes</button><button class="btn small danger" name="status" value="rejected">Reject</button></form></article><?php endforeach;?><?php if(!$rows):?><div class="empty">No listings awaiting review.</div><?php endif;?><?php footer_html();exit;}
if($page==='dashboard'){require_login();$id=$u['id'];header_html('Dashboard');?><h1>Hello, <?=e($u['name'])?></h1><p class="muted">Your <?=e($u['role'])?> workspace.</p><?php if($u['role']==='landlord'):?><a class="btn" href="index.php?page=create">＋ Add a property</a><?php endif;?><?php if($u['role']==='admin'):?><a class="btn" href="index.php?page=admin">Open listing review</a><div class="stats"><?php foreach(['users'=>'Users','properties'=>'Properties','pending'=>'Pending listings'] as $table=>$label){$sql=$table==='pending'?"SELECT COUNT(*) FROM properties WHERE status='pending_review'":"SELECT COUNT(*) FROM $table";$n=db()->query($sql)->fetchColumn();?><div class="stat"><strong><?=e($n)?></strong><span><?=e($label)?></span></div><?php }?></div><?php endif;?>
