if(in_array($u['role'],['landlord','agent','admin'])){$q=db()->prepare("SELECT a.*,p.title,p.owner_id,p.agent_id FROM rental_applications a JOIN properties p ON p.id=a.property_id WHERE p.owner_id=? OR p.agent_id=? ORDER BY a.created_at DESC");$q->execute([$id,$id]);?><h2>Rental applications received</h2><?php foreach($q as $r):?><div class="panel record"><strong><?=e($r['title'])?></strong> · <?=e($r['status'])?><p><?=e($r['message'])?></p><form method="post" class="inlineform"><?=csrf_field()?><input type="hidden" name="action" value="decision"><input type="hidden" name="kind" value="application"><input type="hidden" name="record_id" value="<?=$r['id']?>"><input name="note" placeholder="Decision note"><button class="btn small" name="status" value="under_review">Review</button><button class="btn small" name="status" value="approved">Approve</button><button class="btn small danger" name="status" value="declined">Decline</button></form></div><?php endforeach;?><?php $q=db()->prepare("SELECT v.*,p.title FROM viewing_requests v JOIN properties p ON p.id=v.property_id WHERE p.owner_id=? OR p.agent_id=? ORDER BY v.created_at DESC");$q->execute([$id,$id]);?><h2>Viewing requests</h2><?php foreach($q as $r):?><div class="panel record"><strong><?=e($r['title'])?></strong> · <?=e($r['status'])?><p><?=e($r['requested_at'])?> · <?=e($r['message'])?></p><form method="post" class="inlineform"><?=csrf_field()?><input type="hidden" name="action" value="decision"><input type="hidden" name="kind" value="viewing"><input type="hidden" name="record_id" value="<?=$r['id']?>"><input name="note" placeholder="Decision note"><button class="btn small" name="status" value="accepted">Accept</button><button class="btn small danger" name="status" value="declined">Decline</button></form></div><?php endforeach;?><?php }footer_html();exit;}
