$filters=[];$sql="SELECT p.*,u.name owner_name,(SELECT file_name FROM property_images i WHERE i.property_id=p.id ORDER BY i.sort_order,i.id LIMIT 1) image FROM properties p JOIN users u ON u.id=p.owner_id WHERE p.status='published'";$params=[];foreach(['city','district','property_type'] as $f){if(!empty($_GET[$f])){$sql.=" AND p.$f=?";$params[]=trim($_GET[$f]);}}if(!empty($_GET['max_rent'])){$sql.=' AND p.rent_amount<=?';$params[]=(float)$_GET['max_rent'];}if(!empty($_GET['bedrooms'])){$sql.=' AND p.bedrooms>=?';$params[]=(int)$_GET['bedrooms'];}$sql.=' ORDER BY p.created_at DESC';$q=db()->prepare($sql);$q->execute($params);$properties=$q->fetchAll();header_html('Find a rental home');?><section class="hero"><div><p class="eyebrow">FIND · RENT · MANAGE</p><h1>Find a place<br><em>to call home.</em></h1><p>Explore rental listings and manage your rental journey with more clarity.</p></div><div class="hero-art">⌂<span>🔑</span></div></section><form class="search panel" method="get"><input type="hidden" name="page" value="home"><input name="city" placeholder="City" value="<?=e($_GET['city']??'')?>"><input name="district" placeholder="District" value="<?=e($_GET['district']??'')?>"><select name="property_type"><option value="">Any property type</option><?php foreach(['apartment','house','room','commercial'] as $t):?><option <?=($_GET['property_type']??'')===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select><input name="max_rent" type="number" placeholder="Maximum rent" value="<?=e($_GET['max_rent']??'')?>"><button class="btn">Search properties</button></form><div class="sectionhead"><div><p class="eyebrow">AVAILABLE LISTINGS</p><h2>Explore properties</h2></div><span><?=count($properties)?> results</span></div><div class="cards"><?php foreach($properties as $p):?><article class="propertycard"><a href="index.php?page=property&id=<?=$p['id']?>"><?php if($p['image']):?><img src="uploads/properties/<?=e($p['image'])?>" alt="Property photo"><?php else:?><div class="placeholder">⌂</div><?php endif;?></a><div class="cardbody"><span class="pill"> <?=e($p['property_type'])?></span><h3><a href="index.php?page=property&id=<?=$p['id']?>"><?=e($p['title'])?></a></h3><p><?=e($p['city'])?> · <?=e($p['area'])?></p><strong class="price"><?=money($p['rent_amount'],$p['currency'])?> / <?=e($p['rent_period'])?></strong></div></article><?php endforeach;?></div><?php if(!$properties):?><div class="empty">No properties match these filters yet. Try another search.</div><?php endif;?><?php footer_html();
